/**
 * TodoMVC vanilla application.
 *
 * Behaviour is driven entirely through the DOM: a stable set of seams
 * (create, toggle, toggle-all, clear-completed, edit, route, persist, render)
 * each carry a @planks annotation linking them to the Gherkin step that
 * exercises them. The app self-boots on load and exposes window.__todoInit
 * so a test harness can re-run boot against persisted state (reload).
 */
(function () {
	'use strict';

	var STORE_KEY = 'todos-vanilla';
	var FILTER_KEY = 'todos-vanilla-filter';

	var todos = [];
	var editingId = null;

	/**
	 * @planks("localStorage item {string} is a JSON array")
	 * @planks("each stored todo has the keys {string}")
	 */
	function saveTodos() {
		window.localStorage.setItem(STORE_KEY, JSON.stringify(todos));
	}

	function getTodos() {
		try {
			var raw = window.localStorage.getItem(STORE_KEY);
			return raw ? JSON.parse(raw) : [];
		} catch (e) {
			return [];
		}
	}

	function nextId() {
		var max = 0;
		todos.forEach(function (t) {
			if (t.id > max) max = t.id;
		});
		return max + 1;
	}

	function routeFromHash() {
		var h = window.location.hash;
		if (h === '#/active') return 'active';
		if (h === '#/completed') return 'completed';
		return 'all';
	}

	function getFilter() {
		var f = window.localStorage.getItem(FILTER_KEY);
		if (f === 'active' || f === 'completed' || f === 'all') return f;
		return routeFromHash();
	}

	/**
	 * @planks("the todo list contains {string}")
	 * @planks("the todo list does not contain {string}")
	 * @planks("the todo list is empty")
	 * @planks("the todo list contains only {string}")
	 * @planks("the todo {string} has class {string}")
	 * @planks("the {string} section is hidden")
	 * @planks("the {string} section is visible")
	 * @planks("the toggle-all checkbox is checked")
	 * @planks("the todo-count shows {string}")
	 * @planks("the clear-completed button is hidden")
	 * @planks("the {string} filter link has class {string}")
	 */
	function render() {
		var doc = window.document;
		var listEl = doc.querySelector('.todo-list');
		var mainEl = doc.querySelector('.main');
		var footerEl = doc.querySelector('.footer');
		var countEl = doc.querySelector('.todo-count');
		var toggleAll = doc.querySelector('#toggle-all');
		var clearBtn = doc.querySelector('.clear-completed');
		var filter = getFilter();

		var activeCount = todos.filter(function (t) {
			return !t.completed;
		}).length;
		var hasTodos = todos.length > 0;

		if (mainEl) mainEl.hidden = !hasTodos;
		if (footerEl) footerEl.hidden = !hasTodos;

		if (toggleAll) {
			toggleAll.checked = hasTodos && activeCount === 0;
		}

		if (clearBtn) {
			clearBtn.hidden = !todos.some(function (t) {
				return t.completed;
			});
		}

		if (countEl) {
			var word = activeCount === 1 ? 'item' : 'items';
			countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';
		}

		var visible = todos.filter(function (t) {
			if (filter === 'active') return !t.completed;
			if (filter === 'completed') return t.completed;
			return true;
		});

		if (listEl) {
			listEl.innerHTML = '';
			visible.forEach(function (t) {
				var li = doc.createElement('li');
				li.setAttribute('data-id', String(t.id));
				if (t.completed) li.classList.add('completed');
				if (t.id === editingId) li.classList.add('editing');

				var view = doc.createElement('div');
				view.className = 'view';

				var toggle = doc.createElement('input');
				toggle.type = 'checkbox';
				toggle.className = 'toggle';
				if (t.completed) toggle.checked = true;

				var label = doc.createElement('label');
				label.textContent = t.title;

				var destroy = doc.createElement('button');
				destroy.className = 'destroy';

				view.appendChild(toggle);
				view.appendChild(label);
				view.appendChild(destroy);

				var edit = doc.createElement('input');
				edit.className = 'edit';
				edit.value = t.title;

				li.appendChild(view);
				li.appendChild(edit);
				listEl.appendChild(li);
			});
		}

		var filterLinks = doc.querySelectorAll('.filters a');
		Array.prototype.forEach.call(filterLinks, function (a) {
			var href = a.getAttribute('href');
			var f = href === '#/active' ? 'active' : href === '#/completed' ? 'completed' : 'all';
			if (f === filter) a.classList.add('selected');
			else a.classList.remove('selected');
		});
