	/**
	 * @planks("the user creates a todo with title {string}")
	 */
	function onNewTodoKey(e) {
		if (e.key !== 'Enter' || !e.target.classList.contains('new-todo')) return;
		var val = e.target.value.trim();
		if (!val) return;
		todos.push({ id: nextId(), title: val, completed: false });
		saveTodos();
		e.target.value = '';
		render();
	}

	/**
	 * @planks("the user toggles the todo {string}")
	 */
	function onToggleChange(e) {
		var t = e.target;
		if (!t.classList.contains('toggle')) return;
		var li = t.closest('li');
		if (!li) return;
		var id = Number(li.getAttribute('data-id'));
		var todo = todos.find(function (x) {
			return x.id === id;
		});
		if (!todo) return;
		todo.completed = t.checked;
		saveTodos();
		render();
	}

	/**
	 * @planks("the user toggles all todos")
	 */
	function onToggleAllChange(e) {
		var t = e.target;
		if (t.id !== 'toggle-all') return;
		var checked = t.checked;
		todos.forEach(function (todo) {
			todo.completed = checked;
		});
		saveTodos();
		render();
	}

	/**
	 * @planks("the user clears completed todos")
	 */
	function onClearCompleted(e) {
		if (!e.target.classList.contains('clear-completed')) return;
