			return !t.completed;
		});
		saveTodos();
		render();
	}

	/**
	 * @planks("the user begins editing the todo {string}")
	 */
	function onDblClick(e) {
		var target = e.target;
		if (target.tagName !== 'LABEL') return;
		var li = target.closest('li');
		if (!li) return;
		editingId = Number(li.getAttribute('data-id'));
		render();
	}

	/**
	 * @planks("the user renames the todo {string} to {string}")
	 */
	function commitEdit(input) {
		var li = input.closest('li');
		if (!li) return;
		var id = Number(li.getAttribute('data-id'));
		var todo = todos.find(function (x) {
			return x.id === id;
		});
		if (!todo) {
			editingId = null;
			render();
			return;
		}
		var val = input.value.trim();
		if (val === '') {
			todos = todos.filter(function (x) {
				return x.id !== id;
			});
		} else {
			todo.title = val;
		}
		editingId = null;
		saveTodos();
		render();
	}

	/**
	 * @planks("the user cancels editing of the todo {string}")
	 */
	function cancelEdit() {
		editingId = null;
		render();
	}

	function onEditKey(e) {
		if (!e.target.classList.contains('edit')) return;
		if (e.key === 'Enter') commitEdit(e.target);
		else if (e.key === 'Escape') cancelEdit();
	}

	function onEditBlur(e) {
		if (e.target.classList.contains('edit')) commitEdit(e.target);
	}

	/**
	 * @planks("the user navigates to {string}")
	 */
	function onHashChange() {
		var f = routeFromHash();
		window.localStorage.setItem(FILTER_KEY, f);
		render();
	}

	function onFilterClick(e) {
		var a = e.target.closest('.filters a');
		if (!a) return;
		e.preventDefault();
		window.location.hash = a.getAttribute('href');
	}

	function attach() {
		var doc = window.document;
		doc.addEventListener('change', function (e) {
			onToggleChange(e);
			onToggleAllChange(e);
		});
		doc.addEventListener('click', function (e) {
			onClearCompleted(e);
			onFilterClick(e);
		});
		doc.addEventListener('dblclick', onDblClick);
		doc.addEventListener('keydown', onNewTodoKey);
		doc.addEventListener('keydown', onEditKey);
		doc.addEventListener('blur', onEditBlur, true);
		window.addEventListener('hashchange', onHashChange);
	}

	/**
	 * @planks("the user reloads the page")
	 * @planks("the app loads with no todos")
	 * @planks("the app loads with todos")
	 */
	function init() {
		todos = getTodos();
		editingId = null;
		render();
	}

	if (!window.__todoBooted) {
		attach();
		window.__todoBooted = true;
	}
	window.__todoInit = init;

	if (window.document.readyState === 'loading') {
		window.document.addEventListener('DOMContentLoaded', init);
	} else {
		init();
	}
})();

import { setWorldConstructor } from '@cucumber/cucumber';
import { Window } from 'happy-dom';
