const INDEX_HTML = fs
	.readFileSync(path.resolve('index.html'), 'utf8')
	.replace(/<script[\s\S]*?<\/script>/g, '');
const APP_SRC = fs.readFileSync(path.resolve('js/app.js'), 'utf8');

export class TodoWorld {
	constructor() {
		this.window = new Window({ url: 'http://localhost/' });
		this.document = this.window.document;
		this.window.document.write(INDEX_HTML);
		this.window.eval(APP_SRC);
	}

	findTodoByTitle(title) {
		const lis = Array.from(this.document.querySelectorAll('.todo-list li'));
