import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';

// Walk a directory, returning every .js/.mjs file path.
function walk(dir) {
	const out = [];
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory()) out.push(...walk(full));
		else if (/\.(js|mjs)$/.test(entry.name)) out.push(full);
	}
	return out;
}

// Collect every @planks("...") and @planks-provisional("...") annotation.
function collectPlanks() {
	const out = [];
	for (const file of walk('js')) {
		const src = fs.readFileSync(file, 'utf8');
		const re = /@planks(?:-provisional)?\(\s*"([^"]+)"\s*\)/g;
		let m;
		while ((m = re.exec(src))) out.push({ file, plank: m[1] });
	}
	return out;
}

// Collect every step-definition pattern declared in the support code.
function collectStepPatterns() {
	const patterns = new Set();
	for (const file of walk('features/support')) {
		const src = fs.readFileSync(file, 'utf8');
		const re = /(?:Given|When|Then)\(\s*'([^']+)'\s*,/g;
		let m;
		while ((m = re.exec(src))) patterns.add(m[1]);
	}
	return patterns;
}

function listCaptainScenarios() {
	let out = [];
	try {
		const stdout = execSync(
			'git grep -h -n "^[[:space:]]*Scenario\\|^[[:space:]]*Scenario Outline" features',
			{ encoding: 'utf8' },
		);
		out = stdout
			.split('\n')
			.filter(Boolean)
			.map((line) => line.replace(/^[^:]*:\s*(?:Scenario(?: Outline)?:)\s*/, '').trim());
	} catch (e) {
		/* no scenarios */
	}
	return out;
}

const planks = collectPlanks();
const patterns = collectStepPatterns();
const captainScenarios = listCaptainScenarios();

let failed = false;

for (const { file, plank } of planks) {
	if (plank.startsWith('features/')) {
		// provisional plank: must name a @captain scenario still present
		const scenarioName = plank.slice(plank.indexOf(':') + 1);
		if (!captainScenarios.includes(scenarioName)) {
			console.error('MALFORMED PLANK: ' + file + ' -> ' + plank + ' (no matching @captain scenario)');
			failed = true;
		}
		continue;
	}
	if (!patterns.has(plank)) {
		console.error('STALE PLANK: ' + file + ' -> "' + plank + '" does not match any step definition pattern');
		failed = true;
	} else {
		console.log('JOIN OK: "' + plank + '"');
	}
}

if (!planks.length) {
	console.error('No @planks annotations found in js/');
	failed = true;
}

process.exit(failed ? 1 : 0);

