// Deck-hygiene checks, run as one pass. Each check reports on its own line.
let failed = false;

function check(name, fn) {
	try {
		fn();
		console.log('HYGIENE OK: ' + name);
	} catch (e) {
		console.error('HYGIENE FAIL: ' + name + ' -> ' + e.message);
		failed = true;
	}
}

// 1. No leftover scratch probe file.
check('no scratch probe', () => {
	if (fs.existsSync('probe.mjs')) throw new Error('probe.mjs should be removed');
});

// 2. No PERTURBATION token standing in the working tree diff.
check('no standing PERTURBATION', () => {
	const base = execSync('git rev-parse HEAD', { encoding: 'utf8' }).trim();
	const diff = execSync('git diff ' + base + ' -- . ":!CAPTAIN.md"', { encoding: 'utf8' });
	if (/PERTURBATION/.test(diff)) throw new Error('a PERTURBATION statement stands in the diff');
