check('rigging present', () => {
	if (!fs.existsSync('RIGGING.md')) throw new Error('RIGGING.md missing');
	const rig = fs.readFileSync('RIGGING.md', 'utf8');
	const need = ['## Stack', '## Directories', '## Methods'];
	for (const head of need) {
		if (!rig.includes(head)) throw new Error('RIGGING.md missing ' + head);
	}
});

console.log(failed ? 'Hygiene found faults.' : 'Hygiene clean.');
process.exit(failed ? 1 : 0);

