// Static proof for non-executable hunks (configuration, deletions). A config
// file either loads as valid content or it does not; there is nothing to run.
let failed = false;

function check(name, fn) {
	try {
		fn();
		console.log('STATIC OK: ' + name);
	} catch (e) {
		console.error('STATIC FAIL: ' + name + ' -> ' + e.message);
