import { execFileSync } from 'node:child_process';

const raw = process.env.SS_SCENARIO || '';
const targets = raw
	.split(/\s+/)
	.map((s) => s.trim())
	.filter(Boolean);

const names = targets.map((t) => (t.includes(':') ? t.slice(t.indexOf(':') + 1) : t));
const paths = [
	...new Set(
		targets
			.map((t) => (t.includes(':') ? t.slice(0, t.indexOf(':')) : t))
			.filter(Boolean),
	),
];

const args = [];
if (paths.length) args.push(...paths);
for (const name of names) args.push('--name', name);
args.push('--tags', 'not @captain and not @shipwright');
args.push('--import', 'features/support/world.mjs');
args.push('--import', 'features/support/steps.mjs');

try {
	execFileSync(process.execPath, ['node_modules/@cucumber/cucumber/bin/cucumber.js', ...args], {
		stdio: 'inherit',
	});
	process.exit(0);
} catch (e) {
	process.exit(typeof e.status === 'number' ? e.status : 1);
}

