	const src = fs.readFileSync(file, 'utf8');
	const re = /(?:Given|When|Then)\(\s*(?:\/([^/]+)\/|'([^']+)')\s*,/g;
	let m;
	while ((m = re.exec(src))) {
		if (m[1] !== undefined) patterns.add(m[1]);
		else if (m[2] !== undefined) patterns.add(m[2]);
	}
}

